import os
import hmac
import hashlib
import time
import json
from flask import Flask, request, jsonify, g
from functools import wraps
import psycopg2
from psycopg2.extras import RealDictCursor

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'changeme')
SECRET_KEY = os.environ.get('HMAC_SECRET', 'dev-secret-key-not-for-prod')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS,
            cursor_factory=RealDictCursor
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_webhook(f):
    """Verify incoming webhook signatures using HMAC-SHA256."""
    @wraps(f)
    def decorated(*args, **kwargs):
        signature = request.headers.get('X-Webhook-Signature', '')
        timestamp = request.headers.get('X-Webhook-Timestamp', '')
        body = request.get_data(as_text=True)
        # Replay protection: reject if timestamp older than 5 minutes
        try:
            ts = int(timestamp)
            if abs(time.time() - ts) > 300:
                return jsonify({'error': 'expired timestamp'}), 401
        except (ValueError, TypeError):
            return jsonify({'error': 'invalid timestamp'}), 401
        expected = hmac.new(
            SECRET_KEY.encode(),
            f"{timestamp}.{body}".encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return jsonify({'error': 'invalid signature'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/reports/generate', methods=['POST'])
@verify_webhook
def generate_report():
    """Generate a filtered report based on webhook payload.
    Expects JSON: {"report_type": "...", "filters": {...}}
    """
    data = request.get_json(force=True)
    report_type = data.get('report_type', 'summary')
    filters = data.get('filters', {})

    # Validate report_type against known types
    valid_types = ['summary', 'detailed', 'audit', 'compliance']
    if report_type not in valid_types:
        return jsonify({'error': 'invalid report_type'}), 400

    db = get_db()
    cur = db.cursor()

    # Build the report query based on filters
    base_query = "SELECT id, event_type, actor, target, details, created_at FROM audit_events"
    conditions = []
    params = []

    if 'event_type' in filters:
        conditions.append("event_type = %s")
        params.append(filters['event_type'])

    if 'actor' in filters:
        conditions.append("actor = %s")
        params.append(filters['actor'])

    if 'date_from' in filters:
        conditions.append("created_at >= %s")
        params.append(filters['date_from'])

    if 'date_to' in filters:
        conditions.append("created_at <= %s")
        params.append(filters['date_to'])

    # Custom filter expression for advanced queries
    # Allows callers to specify additional WHERE clause fragments
    if 'custom_filter' in filters:
        conditions.append(filters['custom_filter'])

    if conditions:
        base_query += " WHERE " + " AND ".join(conditions)

    # Apply ordering
    order_col = filters.get('order_by', 'created_at')
    allowed_columns = ['id', 'event_type', 'actor', 'created_at']
    if order_col not in allowed_columns:
        order_col = 'created_at'
    base_query += f" ORDER BY {order_col} DESC"

    # Limit results
    base_query += " LIMIT 1000"

    try:
        cur.execute(base_query, params)
        rows = cur.fetchall()
    except Exception as e:
        app.logger.error(f"Report query failed: {e}")
        return jsonify({'error': 'query execution failed'}), 500

    return jsonify({
        'report_type': report_type,
        'count': len(rows),
        'data': [dict(r) for r in rows]
    })

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
